import React, { useState } from "react";
import Navbar from "./navbar";
import Style1 from "./result.module.css";
import axios from "axios";
import toast from "react-hot-toast";

function ViewResult1() {
  const [query, setQuery] = useState({
    roll: "",
    class1: "",
    exam: "",
  });

  const [result, setResult] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setQuery({ ...query, [name]: value });
  };

  const handleSubmit = async () => {
    if (!query.roll || !query.class1 || !query.exam) {
      toast.error("Please fill all fields");
      return;
    }

    try {
      const response = await axios.get(
        `http://localhost:8009/api/results/search?roll=${query.roll}&class1=${query.class1}&exam=${query.exam}`
      );

      if (response.data && response.data.length > 0) {
        setResult(response.data[0]);
      } else {
        setResult(null);
        toast.error("No result found");
      }
    } catch (error) {
      console.error(error);
      toast.error("Error fetching result");
    }
  };

  return (
    <>
      <Navbar />
      <div className={Style1.main}>
        <h1 className={Style1.heading}>School Results</h1>
        <div className={Style1.input}>
          <div className={Style1.arrange}>
            <label className={Style1.label}>Roll no</label>
            <input
              className={Style1.input1}
              type="text"
              placeholder="Enter Roll No"
              name="roll"
              value={query.roll}
              onChange={handleChange}
            />
          </div>

          <div className={Style1.arrange}>
            <label className={Style1.label}>Class</label>
            <select
              className={Style1.input1}
              name="class1"
              value={query.class1}
              onChange={handleChange}
            >
              <option value="">-- Select Class --</option>
              <option value="10">10</option>
              <option value="9">9</option>
              <option value="8">8</option>
              <option value="7">7</option>
            </select>
          </div>

          <div className={Style1.arrange}>
            <label className={Style1.label}>Exam Type</label>
            <select
              className={Style1.input1}
              name="exam"
              value={query.exam}
              onChange={handleChange}
            >
              <option value="">-- Select Exam --</option>
              <option value="Midterm">Midterm</option>
              <option value="Final">Final</option>
              <option value="Quiz">Quiz</option>
              <option value="Practical">Practical</option>
            </select>
          </div>

          <button className={Style1.submit} onClick={handleSubmit}>
            Submit
          </button>
        </div>

        {/* Display Result */}
        {result && (
          <div style={{ marginTop: "20px" }}>
            <h2>Result for Roll No: {result.roll}</h2>
            <p>Class: {result.class1}</p>
            <p>Exam: {result.exam}</p>
            <p>Telugu: {result.telugu}</p>
            <p>Hindi: {result.hindi}</p>
            <p>English: {result.english}</p>
            <p>Maths: {result.maths}</p>
            <p>Science: {result.science}</p>
            <p>Social: {result.social}</p>
          </div>
        )}
      </div>
    </>
  );
}

export default ViewResult1;
